class StudentRegistration {
    private String studentName;
    private int age;
    private double gpa;

    public StudentRegistration(String name, int age, double gpa) {
        setName(name);
        setAge(age);
        setGpa(gpa);
    }

    public void setName(String name) {
        if (name != null && !name.trim().isEmpty()) {
            this.studentName = name.trim();
        } else {
            this.studentName = "Unknown Student";
        }
    }

    public void setAge(int age) {
        if (age >= 16 && age <= 100) {
            this.age = age;
        } else {
            System.out.println("Age " + age + " is out of bounds [16-100]. Defaulting to 18.");
            this.age = 18;
        }
    }

    public void setGpa(double gpa) {
        if (gpa >= 0.0 && gpa <= 4.0) {
            this.gpa = gpa;
        } else {
            System.out.println("GPA " + gpa + " is invalid. Clamping to 0.0.");
            this.gpa = 0.0;
        }
    }

    public String getStudentName() { return studentName; }
    public int getAge() { return age; }
    public double getGpa() { return gpa; }
}

public class Main {
    public static void main(String[] args) {
        StudentRegistration s = new StudentRegistration("  Farhan  ", 12, 5.5);
        System.out.println("Clean Name: '" + s.getStudentName() + "'");
        System.out.println("Clamped Age: " + s.getAge());
        System.out.println("Clamped GPA: " + s.getGpa());
    }
}

